import { FormEvent, useEffect, useRef, useState } from "react";
import { api } from "./services/api";

type User={id:string;name:string;email:string;role:"ADMIN"|"STAFF";isActive?:boolean};
type Customer={_id:string;customerId:string;name:string;mobile:string;alternateMobile?:string;email?:string;address?:string;city?:string;occupation?:string;pan?:string;aadhaarLast4?:string;notes?:string};
type Loan={_id:string;loanId:string;customerId:Customer;loanType:string;requiredAmount:number;approvedAmount?:number;financeCompany?:string;status:string;commission:number;applicationDate?:string;expectedDisbursementDate?:string;disbursementDate?:string;rejectionReason?:string;notes?:string;assignedTo?:{_id?:string;name?:string;email?:string;role?:string};documents?:{idProof?:boolean;addressProof?:boolean;incomeProof?:boolean;bankStatement?:boolean;customDocuments?:string[];uploads?:Record<string,{originalName:string;storedName:string;size:number;uploadedAt:string}>;customUploads?:Array<{name:string;originalName:string;storedName:string;size:number;uploadedAt:string}>}};
type CarExpense={_id:string;amount:number;category:string;description?:string;date?:string;carId?:{_id?:string;vehicleId?:string;registrationNumber?:string;make?:string;model?:string;year?:number;purchasePrice?:number}};
type Car={_id:string;vehicleId:string;registrationNumber:string;make:string;model:string;year:number;ownerNumber:number;km:number;fuel:string;purchasePrice:number;purchaseDate?:string;notes?:string;expenseTotal?:number;totalInvestment?:number;status:string;sellerId?:Customer;documents?:{carBook?:boolean;carInsurance?:boolean;agreement?:boolean;customDocuments?:string[];uploads?:Record<string,{originalName:string;storedName:string;size:number;uploadedAt:string}>;customUploads?:Array<{name:string;originalName:string;storedName:string;size:number;uploadedAt:string}>}};
type Dashboard={customers:number;activeLoans:number;carsInInventory:number;carsSold:number;totalSales:number;totalInvestment:number;totalProfit:number};

const money=(v:number)=>new Intl.NumberFormat("en-IN",{style:"currency",currency:"INR",maximumFractionDigits:0}).format(v);
const nav=[["Dashboard","Dashboard"],["Loan Dashboard","Loans"],["Applications","Loans"],["Active Loans","Loans"],["Car Buying","Car Buying"],["Car Inventory","Cars"],["Car Sold","Sold"],["Expenses","Expenses"],["Customers","Customers"],["Customer History","Customers"],["Car Profit","Profit"],["Loan Revenue","Loans"],["Reports","Dashboard"]];

export default function App(){
 const [user,setUser]=useState<User|null>(null); const [loading,setLoading]=useState(true);
 useEffect(()=>{api.get("/auth/me").then(r=>setUser(r.data.data)).catch(()=>localStorage.removeItem("sm_token")).finally(()=>setLoading(false))},[]);
 if(loading)return <div className="center-page"><div className="loader-card">Loading SM Associate...</div></div>;
 if(!user)return <Login onLogin={setUser}/>;
 return <ManagementApp user={user} onLogout={()=>{localStorage.removeItem("sm_token");setUser(null)}}/>;
}

type IconName="dashboard"|"loans"|"applications"|"active"|"followup"|"car"|"inventory"|"sold"|"expense"|"customers"|"history"|"profit"|"revenue"|"reports"|"users"|"documents"|"plus"|"arrow"|"bell";
const ICON_PATHS:Record<IconName,string[]>={
 dashboard:["M4 13h6V4H4v9Zm10 7h6V4h-6v16ZM4 20h6v-3H4v3Zm10 0h6v-7h-6v7Z"],
 loans:["M3 6.5h18M5 6.5v11h14v-11M8 10h2m4 0h2m-8 4h8"],
 applications:["M6 3h8l4 4v14H6V3Zm8 0v5h4M9 12h6m-6 4h6"],
 active:["M5 12.5 9.5 17 19 7.5"],
 followup:["M7 3v3m10-3v3M4 8h16M6 12h4m-4 4h7M5 5h14a1 1 0 0 1 1 1v13H4V6a1 1 0 0 1 1-1Z"],
 car:["M5 16h14l-1.2-5H6.2L5 16Zm2.2-5 1.3-3h7l1.3 3M7 16v2m10-2v2M4 16h16"],
 inventory:["M4 7h16v13H4V7Zm3 0V4h10v3M8 11h8"],
 sold:["M6 6h12v14H6zM9 10h6M9 14h4"],
 expense:["M7 3h10v18H7V3Zm3 4h4m-4 4h4m-4 4h4m-4 4h2"],
 customers:["M16 20v-1a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v1m6-9a4 4 0 1 0 0-8 4 4 0 0 0 0 8Zm6-3a3 3 0 1 0 0-6m3 14v-1a4 4 0 0 0-3-3"],
 history:["M4 6h16v12H4V6Zm3 3h10M7 13h6M7 16h4"],
 profit:["M4 19V9m6 10V5m6 14v-8m4 8V3"],
 revenue:["M4 19h16M6 16V9m5 7V6m5 10V4"],
 reports:["M5 4h14v16H5V4Zm3 4h8M8 12h8M8 16h5"],
 users:["M16 20v-2a4 4 0 0 0-4-4H7a4 4 0 0 0-4 4v2m6-10a4 4 0 1 0 0-8 4 4 0 0 0 0 8Zm7-1v6m3-3h-6"],
 plus:["M12 5v14M5 12h14"],
 arrow:["M5 12h14m-6-6 6 6-6 6"],
  bell:["M7 17h10l-1-2V10a4 4 0 0 0-8 0v5l-1 2Zm3 3h4"],
  documents:["M6 3h8l4 4v14H6V3Zm8 0v5h4M9 12h6m-6 4h6"]
};
function AppIcon({name,className=""}:{name:IconName;className?:string}){const paths=ICON_PATHS[name]??ICON_PATHS.dashboard;return <svg className={"app-icon "+className} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.75" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">{paths.map((d,i)=><path key={i} d={d}/>)}</svg>}
function iconForLabel(label:string):IconName{
 if(label==="Dashboard")return "dashboard";
 if(label==="Loan Dashboard")return "loans";
 if(label==="Applications")return "applications";
 if(label==="Active Loans")return "active";
 if(label==="Follow-ups")return "followup";
 if(label==="Car Buying")return "car";
 if(label==="Car Inventory")return "inventory";
 if(label==="Car Sold")return "sold";
 if(label==="Expenses")return "expense";
 if(label==="Customers")return "customers";
 if(label==="Customer History")return "history";
 if(label==="Car Profit")return "profit";
 if(label==="Loan Revenue")return "revenue";
 if(label==="Reports")return "reports";
 if(label==="Documents")return "documents";
 if(label==="Users")return "users";
 return "dashboard";
}

function PremiumSelect({value,onChange,placeholder,options}:{value:string;onChange:(value:string)=>void;placeholder:string;options:{value:string;label:string}[]}){
 const[open,setOpen]=useState(false);const[search,setSearch]=useState("");
 const selected=options.find(x=>x.value===value);const filtered=options.filter(x=>x.label.toLowerCase().includes(search.toLowerCase()));
 useEffect(()=>{
  if(!open)return;
  const closeOther=()=>{setOpen(false);setSearch("")};
  window.addEventListener("premium-select-open",closeOther);
  const handleOutside=(e:MouseEvent)=>{const target=e.target as Node;if(!(target as Element)?.closest?.(".premium-select")){setOpen(false);setSearch("")}};
  document.addEventListener("mousedown",handleOutside);
  return()=>{window.removeEventListener("premium-select-open",closeOther);document.removeEventListener("mousedown",handleOutside)};
 },[open]);
 function toggle(){if(!open){window.dispatchEvent(new Event("premium-select-open"));setOpen(true)}else setOpen(false);setSearch("")}
 return <div className="premium-select">
  <button type="button" className={open?"premium-select-trigger open":"premium-select-trigger"} onClick={toggle} aria-expanded={open}><span className={selected?"selected":"placeholder"}>{selected?.label||placeholder}</span><span className="premium-select-chevron" aria-hidden="true"></span></button>
  {open&&<div className="premium-select-menu"><input autoFocus className="premium-select-search" placeholder="Search..." value={search} onChange={e=>setSearch(e.target.value)}/><div className="premium-select-options">{!filtered.length?<div className="premium-select-empty">No matching results</div>:filtered.map(x=><button type="button" key={x.value} className={x.value===value?"premium-select-option active":"premium-select-option"} onClick={()=>{onChange(x.value);setOpen(false);setSearch("")}}><span>{x.label}</span>{x.value===value&&<span className="premium-select-check">✓</span>}</button>)}</div></div>}
 </div>
}

function PremiumLogo({compact=false}:{compact?:boolean}){return <img className={compact?"brand-logo-image compact":"brand-logo-image"} src="/assets/sm-associate-logo.png" alt="SM Associate" />}

function FormField({label,children,full=false}:{label:string;children:React.ReactNode;full?:boolean}){return <label className={full?"form-field full":"form-field"}><span>{label}</span>{children}</label>}
function NumberStepper({value,onChange,min=0,step=1,placeholder}:{value:string;onChange:(value:string)=>void;min?:number;step?:number;placeholder?:string}){
 const decimals=Math.max(0,String(step).split(".")[1]?.length||0);
 const change=(direction:number)=>{const current=Number(value);const base=Number.isFinite(current)?current:min;const next=Math.max(min,base+(direction*step));onChange(decimals?next.toFixed(decimals):String(Math.round(next)))};
 return <div className="number-stepper"><button type="button" className="number-stepper-btn" aria-label="Decrease value" onClick={()=>change(-1)}>−</button><div className="number-stepper-input-wrap"><input className="number-stepper-input" inputMode={decimals?"decimal":"numeric"} value={value} onChange={e=>onChange(e.target.value)} placeholder={placeholder}/></div><button type="button" className="number-stepper-btn" aria-label="Increase value" onClick={()=>change(1)}>+</button></div>
}
function TopBar({user}:{user:User}){const[q,setQ]=useState("");function submit(e:FormEvent){e.preventDefault();const term=q.trim();if(term)window.dispatchEvent(new CustomEvent("sm-global-search",{detail:{query:term}}))}return <div className="topbar"><div className="topbar-search"><form onSubmit={submit}><span className="search-icon" aria-hidden="true"></span><input aria-label="Search" value={q} onChange={e=>setQ(e.target.value)} placeholder="Search customers, loans, vehicles..." /></form></div><div className="topbar-actions"><button type="button" className="topbar-icon" aria-label="Notifications"><AppIcon name="bell"/></button><div className="topbar-profile"><span className="profile-avatar">{user.name.trim().slice(0,1).toUpperCase()||"S"}</span><span className="profile-copy"><strong>{user.name}</strong><small>{user.role}</small></span><span className="profile-chevron"></span></div></div></div>}

function Login({onLogin}:{onLogin:(u:User)=>void}){
 const[email,setEmail]=useState("");const[password,setPassword]=useState("");const[error,setError]=useState("");const[busy,setBusy]=useState(false);
 async function submit(e:FormEvent){e.preventDefault();setError("");setBusy(true);try{const r=await api.post("/auth/login",{email,password});localStorage.setItem("sm_token",r.data.data.token);onLogin(r.data.data.user)}catch(e:any){setError(e?.response?.data?.message||"Unable to sign in. Please try again.")}finally{setBusy(false)}}
 return <div className="login-page"><div className="login-panel"><PremiumLogo /><h1>Management System</h1><p>Secure access for finance and car operations.</p><form onSubmit={submit}><FormField label="Email"><input type="email" placeholder="Enter email" value={email} onChange={e=>setEmail(e.target.value)} required/></FormField><FormField label="Password"><input type="password" placeholder="Enter password" value={password} onChange={e=>setPassword(e.target.value)} required/></FormField>{error&&<div className="error-box">{error}</div>}<button className="primary-btn" disabled={busy}>{busy?"Signing in...":"Sign in"}</button></form></div></div>
}

function navigateTo(page:string,context?:any){window.dispatchEvent(new CustomEvent("sm-navigate",{detail:{page,context}}))}
function ManagementApp({user,onLogout}:{user:User;onLogout:()=>void}){
 const[page,setPage]=useState("Dashboard");const[context,setContext]=useState<any>(null);
 useEffect(()=>{const handler=(e:Event)=>{const d=(e as CustomEvent).detail||{};setContext(d.context??null);if(d.page)setPage(d.page)};window.addEventListener("sm-navigate",handler);return()=>window.removeEventListener("sm-navigate",handler)},[]);
 const groups=[
  {title:"GENERAL",items:["Dashboard"]},
  {title:"LOAN MANAGEMENT",items:["Loan Dashboard","Applications","Active Loans","Follow-ups"]},
  {title:"CAR MANAGEMENT",items:user.role==="ADMIN"?["Car Buying","Car Inventory","Car Sold","Expenses"]:["Car Buying","Car Inventory"]},
  {title:"CUSTOMER MANAGEMENT",items:["Customers","Customer History"]},
  {title:"PROFIT & REPORTS",items:user.role==="ADMIN"?["Car Profit","Loan Revenue","Reports"]:["Reports"]},
  ...(user.role==="ADMIN"?[{title:"ADMINISTRATION",items:["Users"]}]:[])
 ];
 const activeGroup=groups.findIndex(g=>g.items.includes(page) || (["Create User","User Details"].includes(page)&&g.title==="ADMINISTRATION") || (["Add Customer","Customer Details"].includes(page)&&g.title==="CUSTOMER MANAGEMENT") || (["New Loan","Loan Details","Edit Loan"].includes(page)&&g.title==="LOAN MANAGEMENT") || (["Add Expense","Edit Expense","Expense Details"].includes(page)&&g.title==="CAR MANAGEMENT") || (["Car Buying","Vehicle Details"].includes(page)&&g.title==="CAR MANAGEMENT") || (["Car Sold"].includes(page)&&g.title==="CAR MANAGEMENT"));
 const[openGroup,setOpenGroup]=useState(activeGroup);
 const sidebarPage=page==="Vehicle Details"?"Car Inventory":page==="Expense Details"||page==="Add Expense"||page==="Edit Expense"?"Expenses":page==="Customer Details"?"Customers":page==="User Details"?"Users":page==="Loan Details"?"Applications":page;
 useEffect(()=>{setOpenGroup(activeGroup)},[activeGroup]);
 return <div className="app"><aside className="sidebar"><div className="brand"><PremiumLogo compact /></div><nav>{groups.map((group,index)=><SidebarGroup key={group.title} title={group.title} items={group.items} open={openGroup===index} onToggle={()=>setOpenGroup(openGroup===index?-1:index)} page={sidebarPage} setPage={setPage}/>)}</nav>
 <div className="sidebar-user"><strong>{user.name}</strong><span>{user.role}</span><button onClick={onLogout}>Sign out</button></div></aside>
 <main className="main"><TopBar user={user}/><header><div><span className="eyebrow">SM ASSOCIATE / MANAGEMENT</span><h1>{page}</h1><p>Manage finance, customers and automotive operations.</p></div></header><PageContent page={page} userRole={user.role} context={context}/></main></div>
}
function SidebarGroup({title,items,open,onToggle,page,setPage}:{title:string;items:string[];open:boolean;onToggle:()=>void;page:string;setPage:(x:string)=>void}){
 const groupIcon=title==="GENERAL"?"dashboard":title==="LOAN MANAGEMENT"?"loans":title==="CAR MANAGEMENT"?"car":title==="CUSTOMER MANAGEMENT"?"customers":title==="PROFIT & REPORTS"?"reports":"users";
 return <section className={open?"sidebar-group open":"sidebar-group"}><button type="button" className="sidebar-group-trigger" onClick={onToggle} aria-expanded={open}><span className="sidebar-group-title"><span className="sidebar-group-icon"><AppIcon name={groupIcon}/></span>{title}</span><span className="sidebar-group-chevron" aria-hidden="true"></span></button>{open&&<div className="sidebar-group-menu">{items.map(item=><Nav key={item} label={item} page={page} setPage={setPage}/>)}</div>}</section>
}
function Nav({label,page,setPage}:{label:string;page:string;setPage:(x:string)=>void}){return <button className={page===label?"nav-link active":"nav-link"} onClick={()=>setPage(label)}><span className="nav-icon"><AppIcon name={iconForLabel(label)}/></span><span>{label}</span></button>}

function PageContent({page,userRole,context}:{page:string;userRole:"ADMIN"|"STAFF";context?:any}){
 if(page==="Create User")return <CreateUserPage/>;
 if(page==="Add Customer")return <AddCustomerPage/>;
 if(page==="New Loan")return <NewLoanPage/>;
 if(page==="Add Expense"||page==="Edit Expense")return <ExpenseFormPage expenseId={context?.expenseId} />;
 if(page==="Users")return <UsersPage/>;
 if(page==="Customers"||page==="Customer History")return <CustomersPage historyOnly={page==="Customer History"}/>;
 if(page==="Loans"||page==="Loan Dashboard"||page==="Applications"||page==="Active Loans"||page==="Follow-ups"||page==="Loan Revenue")return <LoansPage filter={page}/>;
 if(page==="Cars"||page==="Car Inventory")return <CarsPage mode={page} userRole={userRole}/>;
 if(page==="Expenses")return <ExpensesPage/>;
 if(page==="Car Profit")return <ProfitPage/>;
 if(page==="Car Buying")return <CarBuyingPage/>;
 if(page==="Car Sold")return <CarSoldPage/>;
 if(page==="User Details")return <UserDetailsPage context={context}/>;
 if(page==="Customer Details")return <CustomerDetailsPage context={context}/>;
 if(page==="Loan Details")return <LoanDetailsPage context={context}/>;
 if(page==="Vehicle Details")return <VehicleDetailsPage context={context}/>;
 if(page==="Expense Details")return <ExpenseDetailsPage context={context}/>;
 return <DashboardPage/>;
}
function UsersPage(){
 const[users,setUsers]=useState<User[]>([]);const[message,setMessage]=useState("");const[error,setError]=useState("");
 const load=()=>api.get("/auth/users").then(r=>setUsers(r.data.data)).catch(e=>setError(e?.response?.data?.message||"Unable to load users."));useEffect(()=>{load()},[]);
 async function changeRole(u:User,role:"ADMIN"|"STAFF"){setMessage("");setError("");try{await api.patch("/auth/users/"+u.id,{role});setMessage("Role updated.");load()}catch(e:any){setError(e?.response?.data?.message||"Unable to update role.")}}
 async function remove(u:User){if(!window.confirm("Warning: This will permanently delete the user. This action cannot be undone.\n\nDo you want to continue?"))return;setMessage("");setError("");try{await api.delete("/auth/users/"+u.id);setMessage("User deleted successfully.");load()}catch(e:any){setError(e?.response?.data?.message||"Unable to delete user.")}}
 return <section className="panel"><div className="panel-head"><div><h2>User Management</h2><p>Manage staff accounts and roles.</p></div><button className="primary-btn" onClick={()=>navigateTo("Create User")}>Create User</button></div>{message&&<div className="success-box">{message}</div>}{error&&<div className="error-box">{error}</div>}<div className="table-wrap"><table><thead><tr><th>Name</th><th>Email</th><th>Role</th><th>Status</th><th>Action</th></tr></thead><tbody>{users.map(u=><tr key={u.id}><td>{u.name}</td><td>{u.email}</td><td><PremiumSelect value={u.role} onChange={value=>changeRole(u,value as "ADMIN"|"STAFF")} placeholder="Select role" options={[{value:"STAFF",label:"STAFF"},{value:"ADMIN",label:"ADMIN"}]}/></td><td><span className="status">{u.isActive?"ACTIVE":"INACTIVE"}</span></td><td><div className="action-buttons"><button className="small-btn" onClick={()=>navigateTo("User Details",{user:u,backTo:"Users"})}>Edit</button><button className="small-btn delete-btn" onClick={()=>remove(u)}>Delete</button></div></td></tr>)}</tbody></table></div></section>
}
function UserViewModal({user,onClose}:{user:User;onClose:()=>void}){return <div className="modal-backdrop"><section className="modal-panel narrow"><div className="panel-head"><div><h2>{user.name}</h2><p>User account details.</p></div><button className="small-btn" onClick={onClose}>Close</button></div><div className="detail-grid"><div><b>Name</b><span>{user.name}</span></div><div><b>Email</b><span>{user.email}</span></div><div><b>Role</b><span>{user.role}</span></div><div><b>Status</b><span>{user.isActive?"ACTIVE":"INACTIVE"}</span></div></div></section></div>}

function ExpenseViewModal({expense,onClose}:{expense:CarExpense;onClose:()=>void}){return <div className="modal-backdrop"><section className="modal-panel narrow"><div className="panel-head"><div><h2>Expense Details</h2><p>{expense.carId?.vehicleId||"Vehicle expense"}</p></div><button className="small-btn" onClick={onClose}>Close</button></div><div className="detail-grid"><div><b>Vehicle</b><span>{expense.carId?.vehicleId||"—"}</span></div><div><b>Registration</b><span>{expense.carId?.registrationNumber||"—"}</span></div><div><b>Category</b><span>{expense.category}</span></div><div><b>Amount</b><span>{money(expense.amount)}</span></div></div><div className="metric-row"><span>Description</span><strong>{expense.description||"—"}</strong></div><div className="metric-row"><span>Date</span><strong>{expense.date?new Date(expense.date).toLocaleDateString("en-IN"):"—"}</strong></div></section></div>}

function CarFinancialModal({state,onClose}:{state:any;onClose:()=>void}){const d=state.details;const car=state.car;return <div className="modal-backdrop"><section className="modal-panel"><div className="panel-head"><div><h2>{car.vehicleId} · {car.make} {car.model}</h2><p>Vehicle financial details.</p></div><button className="small-btn" onClick={onClose}>Close</button></div>{state.loading?<div className="loader-card">Loading vehicle details...</div>:<><div className="detail-grid"><div><b>Registration</b><span>{car.registrationNumber}</span></div><div><b>Purchase Price</b><span>{money(car.purchasePrice)}</span></div><div><b>Expenses</b><span>{money(d?.expenseTotal??0)}</span></div><div><b>Total Investment</b><span>{money(d?.totalInvestment??car.purchasePrice)}</span></div><div><b>Status</b><span className="status">{car.status}</span></div><div><b>KM</b><span>{car.km?.toLocaleString("en-IN")}</span></div></div>{d?.sale&&<div className="modal-section"><h3>Sale</h3><div className="detail-grid"><div><b>Selling Price</b><span>{money(d.sale.sellingPrice)}</span></div><div><b>Selling Expenses</b><span>{money(d.sale.sellingExpenses)}</span></div><div><b>Net Profit</b><span className={d.sale.profit>=0?"profit-positive":"profit-negative"}>{money(d.sale.profit)}</span></div></div></div>}</>}</section></div>}

function BackButton({page}:{page:string}){return <button type="button" className="small-btn" onClick={()=>navigateTo(page)}>← Back</button>}

function CreateUserPage(){
 const[form,setForm]=useState({name:"",email:"",password:"",role:"STAFF"});const[message,setMessage]=useState("");const[error,setError]=useState("");
 async function add(e:FormEvent){e.preventDefault();setMessage("");setError("");try{await api.post("/auth/users",form);setMessage("User created successfully.");setForm({name:"",email:"",password:"",role:"STAFF"})}catch(e:any){setError(e?.response?.data?.message||"Unable to create user.")}}
 return <section className="panel narrow"><div className="panel-head"><div><p>Create a new staff or admin account.</p></div><BackButton page="Users"/></div>{message&&<div className="success-box">{message}</div>}{error&&<div className="error-box">{error}</div>}<form onSubmit={add}><FormField label="Full Name"><input placeholder="Enter full name" value={form.name} onChange={e=>setForm({...form,name:e.target.value})} required/></FormField><FormField label="Email"><input type="email" placeholder="Enter email" value={form.email} onChange={e=>setForm({...form,email:e.target.value})} required/></FormField><FormField label="Password"><input type="password" placeholder="Minimum 8 characters" value={form.password} onChange={e=>setForm({...form,password:e.target.value})} minLength={8} required/></FormField><FormField label="Role"><PremiumSelect value={form.role} onChange={value=>setForm({...form,role:value})} placeholder="Select role" options={[{value:"STAFF",label:"STAFF"},{value:"ADMIN",label:"ADMIN"}]}/></FormField><button className="primary-btn"><AppIcon name="plus"/>Create User</button></form></section>
}

function AddCustomerPage(){
 const[form,setForm]=useState({name:"",mobile:"",email:"",city:"",occupation:""});const[message,setMessage]=useState("");const[error,setError]=useState("");
 async function add(e:FormEvent){e.preventDefault();setMessage("");setError("");try{await api.post("/customers",form);setMessage("Customer added successfully.");setForm({name:"",mobile:"",email:"",city:"",occupation:""})}catch(e:any){setError(e?.response?.data?.message||"Unable to save customer.")}}
 return <section className="panel narrow"><div className="panel-head"><div><p>Customer ID will be generated automatically.</p></div><BackButton page="Customers"/></div>{message&&<div className="success-box">{message}</div>}{error&&<div className="error-box">{error}</div>}<form onSubmit={add}>{[{key:"name",label:"Full Name"},{key:"mobile",label:"Mobile Number"},{key:"email",label:"Email"},{key:"city",label:"City"},{key:"occupation",label:"Occupation"}].map(item=><FormField key={item.key} label={item.label}><input placeholder={"Enter "+item.label.toLowerCase()} value={(form as any)[item.key]} onChange={e=>setForm({...form,[item.key]:e.target.value})} required={item.key==="name"||item.key==="mobile"}/></FormField>)}<button className="primary-btn"><AppIcon name="plus"/>Save Customer</button></form></section>
}

function NewLoanPage(){
 const[customers,setCustomers]=useState<Customer[]>([]);const[customerMode,setCustomerMode]=useState<"EXISTING"|"NEW">("EXISTING");const[newCustomer,setNewCustomer]=useState({name:"",mobile:"",email:"",city:"",occupation:""});const[form,setForm]=useState({customerId:"",loanType:"Home Loan",requiredAmount:"",financeCompany:"",commission:"",notes:""});const[documents,setDocuments]=useState({idProof:false,addressProof:false,incomeProof:false,bankStatement:false,customDocuments:[] as string[]});const[pendingFiles,setPendingFiles]=useState<Record<string,File|undefined>>({});const[customDocumentName,setCustomDocumentName]=useState("");const[showCustomDocumentInput,setShowCustomDocumentInput]=useState(false);const[message,setMessage]=useState("");const[error,setError]=useState("");const[busy,setBusy]=useState(false);
 useEffect(()=>{api.get("/customers").then(r=>setCustomers(r.data.data)).catch(()=>{})},[]);
 const setDocument=(key:"idProof"|"addressProof"|"incomeProof"|"bankStatement",value:boolean)=>{setDocuments(prev=>({...prev,[key]:value}));if(!value)setPendingFiles(prev=>({...prev,[key]:undefined}))};
 const setFile=(key:string,file?:File)=>setPendingFiles(prev=>({...prev,[key]:file}));
 const addCustomDocument=()=>{const name=customDocumentName.trim();if(!name)return;const exists=documents.customDocuments.some(x=>x.toLowerCase()===name.toLowerCase());if(exists){setError("This document name is already added.");return}setDocuments(prev=>({...prev,customDocuments:[...prev.customDocuments,name]}));setCustomDocumentName("");setShowCustomDocumentInput(false);setError("")};
 const removeCustomDocument=(index:number)=>{const name=documents.customDocuments[index];setPendingFiles(prev=>{const next={...prev};delete next["custom:"+name];return next});setDocuments(prev=>({...prev,customDocuments:prev.customDocuments.filter((_,i)=>i!==index)}));};
 async function add(e:FormEvent){e.preventDefault();setMessage("");setError("");try{let customerId=form.customerId;if(customerMode==="NEW"){const customer=await api.post("/customers",newCustomer);customerId=customer.data.data._id}if(!customerId)throw new Error("Select an existing customer or enter a new customer.");const loan=await api.post("/loans",{...form,customerId,requiredAmount:Number(form.requiredAmount),commission:Number(form.commission||0),documents});const createdLoan=loan.data.data.loan||loan.data.data;const loanId=createdLoan._id;const uploads:Array<{key:string;name:string;file:File}>=[];(["idProof","addressProof","incomeProof","bankStatement"] as const).forEach(key=>{if(pendingFiles[key])uploads.push({key,name:"",file:pendingFiles[key]!})});documents.customDocuments.forEach(name=>{const file=pendingFiles["custom:"+name];if(file)uploads.push({key:"custom",name,file})});const failed:string[]=[];for(const item of uploads){const fd=new FormData();fd.append("file",item.file);if(item.key==="custom")fd.append("documentName",item.name);try{await api.post("/loans/"+loanId+"/documents/"+item.key,fd)}catch(_e){failed.push(item.name||item.key)}}setMessage(failed.length?"Loan application created, but these documents could not be uploaded: "+failed.join(", "):uploads.length?"Loan application created and documents uploaded successfully.":"Loan application created successfully.");setForm({customerId:"",loanType:"Home Loan",requiredAmount:"",financeCompany:"",commission:"",notes:""});setNewCustomer({name:"",mobile:"",email:"",city:"",occupation:""});setCustomerMode("EXISTING");setDocuments({idProof:false,addressProof:false,incomeProof:false,bankStatement:false,customDocuments:[]});setPendingFiles({});setCustomDocumentName("");setShowCustomDocumentInput(false)}catch(e:any){setError(e?.response?.data?.message||e?.message||"Unable to create loan.")}}
 return <section className="panel narrow"><div className="panel-head"><div><p>New applications start with status <strong>ENTERED</strong>.</p></div><BackButton page="Applications"/></div>{message&&<div className="success-box">{message}</div>}{error&&<div className="error-box">{error}</div>}<form onSubmit={add}><FormField label="Customer Type"><PremiumSelect value={customerMode} onChange={value=>{const mode=value as "EXISTING"|"NEW";setCustomerMode(mode);setForm({...form,customerId:""})}} placeholder="Select customer type" options={[{value:"EXISTING",label:"Existing Customer"},{value:"NEW",label:"New Customer"}]}/></FormField>{customerMode==="EXISTING"?<FormField label="Customer"><PremiumSelect value={form.customerId} onChange={value=>setForm({...form,customerId:value})} placeholder="Select existing customer" options={customers.map(c=>({value:c._id,label:c.customerId+" — "+c.name+" — "+c.mobile}))}/></FormField>:<div className="form-grid"><FormField label="Customer Name"><input placeholder="Customer name" value={newCustomer.name} onChange={e=>setNewCustomer({...newCustomer,name:e.target.value})} required/></FormField><FormField label="Mobile Number"><input placeholder="Mobile number" value={newCustomer.mobile} onChange={e=>setNewCustomer({...newCustomer,mobile:e.target.value})} required/></FormField><FormField label="Email"><input type="email" placeholder="Email" value={newCustomer.email} onChange={e=>setNewCustomer({...newCustomer,email:e.target.value})}/></FormField><FormField label="City"><input placeholder="City" value={newCustomer.city} onChange={e=>setNewCustomer({...newCustomer,city:e.target.value})}/></FormField><FormField label="Occupation"><input placeholder="Occupation" value={newCustomer.occupation} onChange={e=>setNewCustomer({...newCustomer,occupation:e.target.value})}/></FormField></div>}<FormField label="Loan Type"><PremiumSelect value={form.loanType} onChange={value=>setForm({...form,loanType:value})} placeholder="Select loan type" options={["Home Loan","Car Loan","Business Loan","Personal Loan"].map(x=>({value:x,label:x}))}/></FormField><FormField label="Required Amount"><NumberStepper value={form.requiredAmount} onChange={value=>setForm({...form,requiredAmount:value})} min={0} placeholder="Enter required amount"/></FormField><FormField label="Finance Company"><input placeholder="Enter finance company" value={form.financeCompany} onChange={e=>setForm({...form,financeCompany:e.target.value})}/></FormField><FormField label="Commission"><NumberStepper value={form.commission} onChange={value=>setForm({...form,commission:value})} min={0} placeholder="Enter commission"/></FormField><div className="documents-section"><div className="documents-heading"><div className="section-title-row"><span className="section-title-icon"><AppIcon name="documents"/></span><div><h3>Loan Documents</h3><p>Upload identity, address, income or banking documents for this loan application.</p></div></div><div className="documents-heading-actions"><button type="button" className="small-btn document-add-btn" onClick={()=>setShowCustomDocumentInput(true)}><AppIcon name="plus"/>Add Document</button><span className="section-kicker">DOCUMENT STATUS</span></div></div>{showCustomDocumentInput&&<div className="custom-document-entry"><div className="custom-document-form"><div className="custom-document-input"><span className="custom-document-field-title">Document Name</span><div className="custom-document-input-row"><AppIcon name="documents"/><input autoFocus value={customDocumentName} onChange={e=>setCustomDocumentName(e.target.value)} placeholder="Enter document name" maxLength={100}/></div></div><button type="button" className="small-btn document-save-btn" onClick={addCustomDocument}>Add</button><button type="button" className="small-btn" onClick={()=>{setCustomDocumentName("");setShowCustomDocumentInput(false)}}>Cancel</button></div><small>Example: Property Document, GST Certificate, Salary Slip, ITR, Other Supporting Document</small></div>}<div className="document-grid">{[{key:"idProof" as const,title:"ID Proof",description:"Customer identity proof"},{key:"addressProof" as const,title:"Address Proof",description:"Customer address proof"},{key:"incomeProof" as const,title:"Income Proof",description:"Salary / income supporting document"},{key:"bankStatement" as const,title:"Bank Statement",description:"Recent bank statement"}].map(doc=><div className="document-card" key={doc.key}><label className={documents[doc.key]?"document-item active":"document-item"}><span className="document-icon"><AppIcon name="documents"/></span><span className="document-copy"><strong>{doc.title}</strong><small>{doc.description}</small></span><input type="checkbox" checked={documents[doc.key]} onChange={e=>setDocument(doc.key,e.target.checked)}/><span className="document-check">{documents[doc.key]?"✓":"—"}</span></label>{documents[doc.key]&&<DocumentUploadBox file={pendingFiles[doc.key]} onFile={file=>setFile(doc.key,file)}/>}</div>)}{documents.customDocuments.map(name=><div className="document-card" key={name}><div className="document-item active custom-document-item"><span className="document-icon"><AppIcon name="documents"/></span><span className="document-copy"><strong>{name}</strong><small>Custom loan document</small></span><span className="document-check">Added</span><button type="button" className="document-remove" aria-label={"Remove "+name} onClick={()=>removeCustomDocument(documents.customDocuments.indexOf(name))}>×</button></div><DocumentUploadBox file={pendingFiles["custom:"+name]} onFile={file=>setFile("custom:"+name,file)}/></div>)}</div></div><FormField label="Notes" full><textarea placeholder="Enter notes" value={form.notes} onChange={e=>setForm({...form,notes:e.target.value})}/></FormField><button className="primary-btn" disabled={busy}><AppIcon name="plus"/>{busy?"Saving loan & documents...":"Create Application"}</button></form></section>
}

function ExpenseFormPage({expenseId}:{expenseId?:string}){
 const[cars,setCars]=useState<Car[]>([]);const[form,setForm]=useState({carId:"",category:"Service",amount:"",description:"",date:new Date().toISOString().slice(0,10)});const[message,setMessage]=useState("");const[error,setError]=useState("");
 const editing=Boolean(expenseId);
 useEffect(()=>{api.get("/cars",{params:{status:"AVAILABLE"}}).then(r=>setCars(r.data.data)).catch(()=>{});if(expenseId){api.get("/cars/expenses").then(r=>{const x=(r.data.data||[]).find((e:any)=>e._id===expenseId);if(x)setForm({carId:x.carId?._id||x.carId||"",category:x.category,amount:String(x.amount),description:x.description||"",date:x.date?new Date(x.date).toISOString().slice(0,10):new Date().toISOString().slice(0,10)})}).catch(()=>{})}},[expenseId]);
 async function save(e:FormEvent){e.preventDefault();setMessage("");setError("");try{if(editing){const carId=form.carId;await api.patch("/cars/"+carId+"/expenses/"+expenseId,{category:form.category,amount:Number(form.amount),description:form.description,date:form.date});setMessage("Expense updated successfully.")}else{if(!form.carId)throw new Error("Select a vehicle.");await api.post("/cars/"+form.carId+"/expenses",{category:form.category,amount:Number(form.amount),description:form.description,date:form.date});setMessage("Expense added successfully.");setForm({carId:"",category:"Service",amount:"",description:"",date:new Date().toISOString().slice(0,10)})}}catch(e:any){setError(e?.response?.data?.message||e?.message||"Unable to save expense.")}}
 return <section className="panel narrow"><div className="panel-head"><div><p>{editing?"Update the selected expense.":"Add an expense to the vehicle's total investment."}</p></div><BackButton page="Expenses"/></div>{message&&<div className="success-box">{message}</div>}{error&&<div className="error-box">{error}</div>}<form onSubmit={save}>{!editing&&<FormField label="Vehicle"><PremiumSelect value={form.carId} onChange={value=>setForm({...form,carId:value})} placeholder="Select vehicle" options={cars.map(c=>({value:c._id,label:c.vehicleId+" — "+c.registrationNumber+" — "+c.make+" "+c.model}))}/></FormField>}<FormField label="Category"><PremiumSelect value={form.category} onChange={value=>setForm({...form,category:value})} placeholder="Select category" options={["Service","Repair","Tyres","Insurance","Cleaning","Accessories","RC / Documents","Other"].map(x=>({value:x,label:x}))}/></FormField><FormField label="Expense Amount"><NumberStepper value={form.amount} onChange={value=>setForm({...form,amount:value})} min={0} step={0.01} placeholder="Enter expense amount"/></FormField><FormField label="Date"><input type="date" value={form.date} onChange={e=>setForm({...form,date:e.target.value})}/></FormField><FormField label="Description" full><textarea placeholder="Enter description" value={form.description} onChange={e=>setForm({...form,description:e.target.value})}/></FormField><button className="primary-btn">{editing?"Update Expense":"Add Expense"}</button></form></section>
}

